-- Re-seed ASV stock (schema columns: hospital_id, batch_code, quantity, expiry_date, product, updated_by)
INSERT INTO asv_stock (hospital_id, batch_code, quantity, expiry_date, product, updated_by)
SELECT h.id,
       'ASV-' || upper(left(replace(replace(h.name, ' ', ''), '-', ''), 12)) || '-B1',
       (h.raw->'resources'->'asv'->>'quantity')::int,
       (current_date + interval '18 months')::date,
       'Lyophilized ASV 10ml vial',
       'system-seed'
FROM hospitals h
WHERE (h.raw->'resources'->'asv'->>'quantity')::int > 0;

-- Re-point staff accounts to the new hospital rows so their dashboards work
UPDATE staff_users
SET hospital_id = (SELECT id FROM hospitals WHERE name = 'AIIMS New Delhi')
WHERE username = 'admin1';

UPDATE staff_users
SET hospital_id = (SELECT id FROM hospitals WHERE name = 'Safdarjung Hospital')
WHERE username IN ('doctor1', 'reception1');
